113:   getIndexForm(nombre: String): number {
114:     for (let index = 0; index < this.formInfoPersona.campos.length; index++) {
115:       const element = this.formInfoPersona.campos[index];
116:       if (element.nombre === nombre) {
117:         return index;
118:       }
119:     }
120:     return 0;
