124:     if (this.info_persona_id !== null) {
125:       const infoPersona: any = await this.recuperarInfoPersona(); 
126:       if (infoPersona !== null && infoPersona.Id !== undefined) {
127:         const temp = <InfoPersona>infoPersona;
128:         this.aceptaTerminos = true;
129:         this.info_info_persona = temp;
130:         this.datosEncontrados = { ...infoPersona };
131:         const files = [];
132:         this.formInfoPersona.btn = '';
