134:           this.formInfoPersona.campos[this.getIndexForm('Genero')].valor = temp.Genero;
135:         }
136:         this.formInfoPersona.campos[this.getIndexForm('TipoIdentificacion')].valor = temp.TipoIdentificacion;
137:         if (temp.FechaNacimiento != null) {
138:           temp.FechaNacimiento = temp.FechaNacimiento.replace('T00:00:00Z', 'T05:00:00Z');
139:           this.formInfoPersona.campos[this.getIndexForm('FechaNacimiento')].valor = moment(temp.FechaNacimiento, 'YYYY-MM-DDTHH:mm:ss').tz('America/Bogota').toDate();
