195:               // Si el campo existe en la respuesta entonces lo deshabilito
196:               if (res[0].hasOwnProperty(campo.nombre)) {
197:                 // mirar que el campo tenga un valor
198:                 if (res[0][campo.nombre] != null) {
199:                   campo.deshabilitar = true;
200:                 }
