424:   validarTerminos(event: any) {
425:     Swal.fire({
426:       title: this.translate.instant('GLOBAL.terminos_datos'),
427:       width: 800,
428:       allowOutsideClick: false,
429:       allowEscapeKey: true,
430:       html:
431:         '<embed src=' +
432:         environment.apiUrl +
433:         'assets/pdf/politicasUD.pdf' +
434:         ' type="application/pdf" style="width:100%; height:375px;" frameborder="0"></embed>',
435:       input: 'checkbox',
436:       inputPlaceholder: this.translate.instant('GLOBAL.acepto_terminos'),
437:       confirmButtonText: this.translate.instant('GLOBAL.aceptar'),
438:     }).then((result: any) => {
439:       if (result.value) {
440:         this.aceptaTerminos = true;
441:         if (this.existePersona || this.faltandatos) {
442:           this.popUpManager.showPopUpGeneric(this.translate.instant('GLOBAL.actualizar'), this.translate.instant('GLOBAL.actualizar_info_persona'), 'warning', true)
443:             .then((action) => {
444:               if (action.value) {
445:                 this.updateInfoPersona(event.data.InfoPersona);
446:               } else {
447:                 this.aceptaTerminos = false;
448:               }
449:             });
450:         } else {
451:           this.popUpManager.showPopUpGeneric(this.translate.instant('GLOBAL.crear'), this.translate.instant('GLOBAL.crear_info_persona'), 'warning', true)
452:             .then((action) => {
453:               if (action.value) {
454:                 this.createInfoPersona(event.data.InfoPersona);
455:               } else {
456:                 this.aceptaTerminos = false;
457:               }
458:             });
459:         }
460:       } else if (result.value === 0) {
461:         Swal.fire({
462:           icon: 'error',
463:           text: this.translate.instant('GLOBAL.rechazo_terminos'),
464:           confirmButtonText: this.translate.instant('GLOBAL.aceptar'),
465:         });
466:         this.aceptaTerminos = false;
467:       }
468:     });
469:   }
470: 
471:   setPercentage(event: any) {
472:     if (this.aceptaTerminos) {
473:       this.percentage = event;
474:     } else {
475:       this.percentage = event * 0.98;
476:     }
477:     this.result.emit(this.percentage);
478:     if (event < 1.0) {
479:       this.formInfoPersona.campos.forEach((campo: any) => {
480:         if (!campo.valor) {
481:           campo.deshabilitar = false;
482:         }
483:       });
484:       this.formInfoPersona.btn = this.translate.instant('GLOBAL.guardar');
485:       this.faltandatos = true;
486:     }
487:   }
488: 
489:   public loadLists() {
490:     this.store.select((state) => state).subscribe((list) => {
491:         if (list.listGenero && Array.isArray(list.listGenero)) {
492:           this.formInfoPersona.campos[this.getIndexForm('Genero')].opciones = (<any>list.listGenero[0]).filter((g: any) => g.Nombre != 'NO APLICA');
493:         }
494:         if (list.listTipoIdentificacion && Array.isArray(list.listTipoIdentificacion)) {
495:           this.formInfoPersona.campos[this.getIndexForm('TipoIdentificacion')].opciones = list.listTipoIdentificacion[0];
496:         }
497:       });
498:   }
