10: @Injectable({ providedIn: 'root' })
11: export class DiplomasApiService {
12:   private readonly http = inject(HttpClient);
13:   private readonly baseUrl = inject(DIPLOMAS_SERVICE_BASE_URL).replace(/\/$/, '');
14: 
15:   getFirmanteActivo(documento: number): Observable<FirmanteActivo> {
16:     const params = new HttpParams().set('documento_identidad', String(documento));
17:     return this.http
18:       .get<FirmanteActivo>(`${this.baseUrl}/firmantes/rol-activo`, { params, headers: this.authHeaders() })
19:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'firmante'))));
20:   }
21: 
22:   subirFirma(payload: SubirFirmaFirmanteRequest): Observable<SubirFirmaFirmanteResult> {
23:     return this.http
24:       .post<SubirFirmaFirmanteResult>(`${this.baseUrl}/firmantes/firma`, payload, { headers: this.authHeaders() })
25:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'firma'))));
26:   }
27: 
28:   getTableroCeremonias(documento: number): Observable<TableroCeremoniasResult> {
29:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
30:     return this.http
31:       .get<TableroCeremoniasResult>(`${this.baseUrl}/ceremonias`, { params, headers: this.authHeaders() })
32:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
33:   }
34: 
35:   actualizarCeremonia(id: number, payload: ActualizarCeremoniaRequest): Observable<unknown> {
36:     return this.http
37:       .put(`${this.baseUrl}/ceremonias/${id}`, payload, { headers: this.authHeaders() })
38:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
39:   }
40: 
41:   eliminarCeremonia(id: number, documento: number): Observable<unknown> {
42:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
43:     return this.http
44:       .delete(`${this.baseUrl}/ceremonias/${id}`, { params, headers: this.authHeaders() })
45:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
46:   }
47: 
48:   asignarEstudiantesCeremonia(id: number, payload: AsignarEstudiantesCeremoniaRequest): Observable<AsignarEstudiantesCeremoniaResult> {
49:     return this.http
50:       .post<AsignarEstudiantesCeremoniaResult>(`${this.baseUrl}/ceremonias/${id}/asignar`, payload, { headers: this.authHeaders() })
51:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
52:   }
53: 
54:   quitarProgramaCeremonia(id: number, payload: QuitarProgramaCeremoniaRequest): Observable<AsignarEstudiantesCeremoniaResult> {
55:     return this.http
56:       .delete<AsignarEstudiantesCeremoniaResult>(`${this.baseUrl}/ceremonias/${id}/programa`, { body: payload, headers: this.authHeaders() })
57:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
58:   }
59: 
60:   getEstudiantesProgramaCeremonia(programaId: number, documento: number): Observable<EstudiantesProgramaCeremoniaResult> {
61:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
62:     return this.http
63:       .get<EstudiantesProgramaCeremoniaResult>(`${this.baseUrl}/ceremonias/programas/${programaId}/estudiantes`, { params, headers: this.authHeaders() })
64:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
65:   }
66: 
67:   crearCeremonia(payload: CrearCeremoniaRequest): Observable<CrearCeremoniaResult> {
68:     return this.http
69:       .post<CrearCeremoniaResult>(`${this.baseUrl}/ceremonias`, payload, { headers: this.authHeaders() })
70:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
71:   }
72: 
73:   private authHeaders(): HttpHeaders {
74:     const token = localStorage.getItem('access_token');
75:     return token ? new HttpHeaders({ Authorization: `Bearer ${token}` }) : new HttpHeaders();
76:   }
77: 
78:   private normalizarError(error: HttpErrorResponse, contexto: 'firmante' | 'firma' | 'ceremonia'): Error {
79:     if (error.status === 0) {
80:       return new Error('No fue posible conectar con diplomas_service. Verifique la red e intente nuevamente.');
81:     }
82:     if (contexto === 'firmante' && (error.status === 404 || error.status === 422 || error.status === 500)) {
83:       return new Error('No se encontró un firmante activo para el documento ingresado.');
84:     }
85:     if (error.status === 401 || error.status === 403) {
86:       return new Error('No tiene permisos para realizar esta acción.');
87:     }
88:     if (contexto === 'firma') {
89:       return new Error('No fue posible cargar la firma. Intente nuevamente.');
90:     }
91:     if (contexto === 'ceremonia') {
92:       return new Error('No fue posible registrar la ceremonia. Revise los datos e intente nuevamente.');
93:     }
94:     return new Error('No fue posible procesar la solicitud. Intente nuevamente.');
95:   }
96: }

